import { Alert } from '@absoluteui/components/alert';

const host = document.createElement('div');
document.body.append(host);
Alert.create(host, {
  tone: 'info',
  title: 'Scheduled maintenance',
  message: 'The service is read-only on Sunday from 02:00 to 04:00 UTC.',
  dismissible: true,
});

import { Alert, type AlertActionDetail } from '@absoluteui/components/alert';

const host = document.createElement('div');
document.body.append(host);
const alert = Alert.create(host, {
  tone: 'error',
  live: 'assertive',
  title: 'Could not save',
  message: 'Check your connection and try again.',
  actions: [{ label: 'Retry', value: 'retry', variant: 'primary' }],
});
host.addEventListener('aui-action', (event) => {
  if ((event as CustomEvent<AlertActionDetail>).detail.value === 'retry') {
    alert.update({ tone: 'info', title: 'Retrying', message: 'Saving again.' });
  }
});
